INSERT INTO "public"."feature_flags" ("id", "key", "value", "description", "updatedAt") VALUES ('0acf8c83-dec3-45b8-a55d-bf9d1025848e', 'AUDIT_TRAIL', true, 'Habilita o registro de trilha de auditoria para alterações críticas.', '2026-07-13 22:14:15.766'), ('1c26bf36-4b67-4723-80c0-a78d5a092a2c', 'INTELLIGENCE_ARTIFICIAL_DIAG', true, 'Habilita recursos de Inteligência Artificial para sugestão de diagnósticos, análise automática de fotos e previsões de estoque.', '2026-07-13 21:31:01.644'), ('28d1c25f-cfbb-4e29-865b-d0214dd6cf44', 'CLIENT_360_AND_BASE_INSTALADA', true, 'Habilita a Data Table de clientes, Visão 360º em drawer, motor de recorrência e o onboarding progressivo de ativos legados (Lazy Loading).', '2026-07-17 13:12:10.007'), ('2bfa3adc-353b-41f0-a963-97ae1ff84065', 'STRESS_TEST', true, 'Habilita o Teste de Estresse com cronômetro e bloqueio de arraste.', '2026-07-13 22:47:18.256'), ('3102d4fa-d3a5-40f1-a30e-3369422322dd', 'FINANCIAL_DASHBOARD', true, 'Visão consolidada de receitas, despesas, margens de lucro operacional da oficina e ranking de produtividade de técnicos.', '2026-07-13 19:42:40.196'), ('37483513-878b-4ab8-970e-9c9390fe5882', 'CLIENT_PORTAL', true, 'Habilita o Portal Público do Cliente com timeline de reparo, fotos de laudo, download de documentos e aprovação de orçamento online.', '2026-07-13 19:57:41.108'), ('52e72861-81f3-46fd-bd96-8407468be6d0', 'MANDATORY_CHECKLIST', true, 'Habilita a exigência de preenchimento do checklist de entrada padronizado e laudo com fotos do equipamento.', '2026-07-13 21:31:03.679'), ('5bfbe726-f896-4cb3-9321-ad07c2aa8f18', 'FISCAL_NFE_EMISSION', true, 'Emissão automática de NFe/NFCe na SEFAZ e sincronização bidirecional de clientes/peças com o Bling ERP V3.', '2026-07-13 19:42:42.556'), ('7c02f595-79ae-4cde-aba2-2cec8007ab85', 'SMART_KANBAN', true, 'Habilita o Kanban Inteligente com validações de qualidade.', '2026-07-13 22:14:20.067'), ('7cfc69ec-aa1d-4b1b-ad7f-aecc01aae722', 'OS_PROFITABILITY_CALC', true, 'Habilita o módulo de Rentabilidade por OS (Custo vs Lucro) e modal gerencial para o perfil OWNER.', '2026-07-14 18:54:55.157'), ('802c47da-2cc3-4494-9eb8-28e3f1ac1cc1', 'DEVICE_TIMELINE', true, 'Habilita a Timeline Visual do Equipamento (Prontuário Técnico).', '2026-07-13 22:14:06.518'), ('97fc8d05-22ef-40cf-884e-c22591eb79e1', 'OS_MANUAL_ITEMS', true, 'Ao habilitar esta flag, o botão "+ Item Avulso" passará a ficar disponível para os usuários na visualização da OS!', '2026-07-13 15:17:52.883'), ('9ceb830c-6081-486f-83dc-1c1e3a9703d7', 'AUTOMATIONS_AND_ALERTS', true, 'Habilita a automação de tarefas, alertas inteligentes de ociosidade, fechamento automático de OS e agendamentos de revisões.', '2026-07-13 19:31:35.718'), ('9d69bd44-ae49-4ee9-997d-88073136842b', 'PIPEFY_SPLIT_MODAL', true, '', '2026-07-15 15:38:40.278'), ('ad8ea96a-eb03-4579-b8bb-8b775a6adc24', 'WHATSAPP_AUTO_MESSAGES', true, 'Habilita o envio automático de WhatsApp para mudança de status, orçamento pronto e lembretes de retirada, além do histórico de mensagens.', '2026-07-13 19:29:55.226'), ('eb225816-bb5e-4c39-bbb6-3e356f7475e6', 'STOCK_RESERVATION', true, 'Reserva lógica automática de peças ao iniciar reparos, alertas de estoque mínimo e exigência de número de série para peças caras.', '2026-07-14 18:54:54.868'), ('ede336d2-1526-435e-b3f3-a77a67e2d287', 'CHECKLIST_SAIDA', true, 'Habilita o Checklist de Saída configurável por categoria de equipamento.', '2026-07-13 22:14:24.401'), ('f50faeee-d638-4249-bfa1-9ee45861e81b', 'STRESS_TEST_FLOW', true, 'Habilita o cronômetro inteligente para testes de estresse de 30 minutos na bancada e travas no Kanban do técnico.', '2026-07-13 21:31:06.119');